package com.nthexperience.desktop;

import android.content.Context;
import android.graphics.Color;
import android.view.*;
import android.widget.*;
import org.json.*;

final class GadgetGallery extends VistaShell {
    interface Host extends Actions {void changed();void reveal();}
    private final WeatherClient weather;private final Host host;private String category="All gadgets";
    private static final String[] CATEGORIES={"All gadgets","Time","Information","Productivity","Device","Photos","Games"};
    GadgetGallery(Context c,DesktopStore store,WeatherClient weather,Host host){super(c,store,host,"Search Gadget Gallery");this.weather=weather;this.host=host;TextView show=command("Show Sidebar",host::reveal);show.setContentDescription("Show Sidebar");commands.addView(show,new LayoutParams(-2,dp(36)));commands.addView(command("Category ▾",this::categories),new LayoutParams(-2,dp(36)));start("home");}
    @Override void render(){
        side.removeAllViews();for(String name:CATEGORIES)sideLink(name,()->{category=name;render();});sideLink("Personalization",()->host.open("@appearance"));address.setText("Desktop Gadget Gallery  ›  "+category);LinearLayout column=column();heading(column,"Add gadgets to your desktop","Choose a gadget, view its details, or open its settings.");TextView hint=Aero.text(getContext(),"Hold a desktop gadget to drag it. Use ⋮ for docking and sizes, and ◢ to resize.",12,0xff586976);hint.setTypeface(android.graphics.Typeface.create(Aero.face(getContext()),android.graphics.Typeface.ITALIC));column.addView(hint);GridLayout grid=new GridLayout(getContext());grid.setColumnCount(2);column.addView(grid,new LayoutParams(-1,-2));int count=0;
        for(String[] item:GadgetCatalog.ITEMS){String id=item[0];if(!category.equals("All gadgets")&&!category.equals(item[2]))continue;if(!query().isEmpty()&&!(item[1]+" "+item[2]+" "+item[3]).toLowerCase(java.util.Locale.ROOT).contains(query()))continue;count++;LinearLayout cell=Aero.column(getContext());cell.setGravity(Gravity.CENTER);cell.setPadding(dp(5),dp(6),dp(5),dp(8));FrameLayout preview=new FrameLayout(getContext());preview.setBackground(Aero.panel(getContext(),0xffe2edf3,0xffbacfdd,4,0xffa4b9c7));GadgetView face=new GadgetView(getContext(),id,store,weather);preview.addView(face,new FrameLayout.LayoutParams(dp(102),dp(110),Gravity.CENTER));preview.setContentDescription("Open "+item[1]+" gadget settings");preview.setOnClickListener(v->open(id));cell.addView(preview,new LayoutParams(-1,dp(115)));TextView title=Aero.text(getContext(),item[1],13,Aero.INK);title.setGravity(Gravity.CENTER);cell.addView(title,new LayoutParams(-1,dp(30)));TextView toggle=Aero.button(getContext(),store.gadgets().contains(id)?"Remove":"Add",()->{});toggle.setContentDescription((store.gadgets().contains(id)?"Remove ":"Add ")+item[1]+" gadget");toggle.setOnClickListener(v->{java.util.List<String> enabled=store.gadgets();if(enabled.contains(id))enabled.remove(id);else enabled.add(id);store.gadgets(enabled);host.changed();if(enabled.contains(id))host.reveal();toggle.setText(enabled.contains(id)?"Remove":"Add");toggle.setContentDescription((enabled.contains(id)?"Remove ":"Add ")+item[1]+" gadget");status.setText(GadgetCatalog.IDS.length+" available gadgets  •  "+enabled.size()+" on your desktop");});cell.addView(toggle,new LayoutParams(-1,dp(40)));TextView settings=link(cell,"Settings",()->open(id));settings.setGravity(Gravity.CENTER);settings.setContentDescription("Settings for "+item[1]+" gadget");TextView details=link(cell,"Show details",()->Aero.dialog(getContext()).setTitle(item[1]).setMessage(item[3]+"\n\nCategory: "+item[2]+"\nNative Nth gadget • Version "+AppInfo.version(getContext())+"\n\nDock in the Sidebar or move it onto the desktop. Your settings are saved.").setPositiveButton("OK",null).show());details.setGravity(Gravity.CENTER);details.setContentDescription("Details for "+item[1]+" gadget");GridLayout.LayoutParams p=new GridLayout.LayoutParams();p.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);p.width=0;p.bottomMargin=dp(8);grid.addView(cell,p);}
        if(count==0)heading(column,"No matching gadgets","Try another category or clear your search.");CheckBox lock=Aero.check(getContext(),"Lock desktop layout",store.prefs.getBoolean("layout_locked",false));lock.setContentDescription("Lock desktop layout");lock.setOnCheckedChangeListener((v,value)->store.prefs.edit().putBoolean("layout_locked",value).apply());column.addView(lock);CheckBox snap=Aero.check(getContext(),"Snap gadgets to grid",store.prefs.getBoolean("snap_gadgets",true));snap.setOnCheckedChangeListener((v,value)->store.prefs.edit().putBoolean("snap_gadgets",value).apply());column.addView(snap);status.setText(count+" available gadgets  •  "+store.gadgets().size()+" on your desktop");body(scrolling(column));
    }
    private void open(String kind){host.action("gadget:"+kind);}
    private void categories(){DesktopContextMenu menu=new DesktopContextMenu(getContext(),"Gadget categories");for(String name:CATEGORIES)menu.checked(name,name.equals(category),()->{category=name;render();});ContextMenus.centered(commands,(x,y)->ContextMenus.show(menu,commands,x,y));}
    @Override void showFolders(){categories();}
    @Override void goUp(){category="All gadgets";render();}
    @Override JSONObject extraState(){JSONObject state=new JSONObject();GadgetLayout.put(state,"category",category);return state;}
    @Override void restoreExtra(JSONObject state){if(state!=null&&java.util.Arrays.asList(CATEGORIES).contains(state.optString("category")))category=state.optString("category");}
    @Override void refreshApps(){render();}
}
